import type { NavRole } from '@/components/app/sidebar/nav-config'

export const metadata: Metadata = {
  title: 'Appointments — InkOS',
}

const APPOINTMENTS_TABS: PageTab[] = [
  {
    key: 'list',
    label: 'All',
    href: '/appointments?tab=list',
  },
  {
    key: 'today',
    label: 'Today',
    href: '/appointments?tab=today',
  },
  {
    key: 'waitlist',
    label: 'Waitlist',
    href: '/appointments?tab=waitlist',
    hidden: (role) =>
      role !== 'owner' && role !== 'admin' && role !== 'receptionist',
  },
]

const VALID_KEYS = new Set(APPOINTMENTS_TABS.map((t) => t.key))

interface Props {
  searchParams: Promise<Record<string, string | string[] | undefined>>
}

export default async function AppointmentsPage({ searchParams }: Props) {
  const auth = await getAuthenticatedUser()
  if (!auth) redirect('/login')

  const supabase = await createClient()
  let plan: PlanTier = 'solo'
  const { data: sub } = await supabase
    .from('subscriptions')
    .select('plan_tier')
    .eq('studio_id', auth.studioId)
    .eq('status', 'active')
    .maybeSingle()
  if (sub?.plan_tier) plan = sub.plan_tier as PlanTier

  const role = auth.role as NavRole
  const params = await searchParams
  const rawTab = typeof params.tab === 'string' ? params.tab : undefined
  const activeKey = rawTab && VALID_KEYS.has(rawTab) ? rawTab : 'list'

  return (
    <div className="flex flex-col flex-1 min-h-0">
      {/* Page header */}
      <div className="flex items-center justify-between px-6 pt-6 pb-0">
        <div>
          <h1 className="text-2xl font-bold tracking-tight text-foreground">Appointments</h1>
          <p className="mt-0.5 text-sm text-muted-foreground">Manage all studio bookings</p>
        </div>
      </div>

      {/* Tab row */}
      <div className="px-6 mt-4">
        <PageTabs
          tabs={filterTabsForRole(APPOINTMENTS_TABS, role)}
          activeKey={activeKey}
          currentPlan={plan}
          currentRole={role}
        />
      </div>

      {/* Tab content */}
      <div role="tabpanel" id={`tabpanel-${activeKey}`} className="flex flex-col flex-1 min-h-0">
        <Suspense fallback={<div className="flex-1 animate-pulse bg-muted/20 m-6 rounded-xl" />}>
          {activeKey === 'list' && <AppointmentsPageClient />}
          {activeKey === 'today' && <AppointmentsPageClient forceToday />}
          {activeKey === 'waitlist' && <WaitlistPageClient />}
        </Suspense>
      </div>
    </div>
  )
}

